"""Emit gen_segments.h from an analysis json: emit_runtime.py <analysis json> <out header>."""

from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any

HEADER = """\
/* Generated by tools/hobbit/emit_runtime.py from recon/analysis.json. Do not edit. */
#ifndef GEN_SEGMENTS_H
#define GEN_SEGMENTS_H

#include <stdint.h>

typedef struct {
    const char *name;
    uint32_t vmaddr;
    uint32_t vmsize;
    uint32_t fileoff;
    uint32_t filesize;
    uint32_t initprot;
} guest_segment_t;

static const guest_segment_t GUEST_SEGMENTS[] = {
"""


def render(analysis: dict[str, Any]) -> str:
    lines = [HEADER]
    segments: list[dict[str, Any]] = analysis["segments"]
    for seg in segments:
        lines.append(
            '    {"%s", 0x%x, 0x%x, 0x%x, 0x%x, %d},\n'
            % (
                seg["name"],
                seg["vmaddr"],
                seg["vmsize"],
                seg["fileoff"],
                seg["filesize"],
                seg["initprot"],
            )
        )
    lines.append("};\n\n")
    lines.append(
        "#define GUEST_SEGMENT_COUNT "
        "(sizeof(GUEST_SEGMENTS) / sizeof(GUEST_SEGMENTS[0]))\n\n#endif\n"
    )
    return "".join(lines)


def main() -> None:
    if len(sys.argv) != 3:
        sys.exit("usage: emit_runtime.py <analysis json> <out header>")
    analysis = json.loads(Path(sys.argv[1]).read_text())
    output = Path(sys.argv[2])
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(render(analysis))


if __name__ == "__main__":
    main()
